ontology_content:
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix ex:   <http://example.org/fintech/> .

ex:FintechOntology a owl:Ontology ;
    rdfs:label "Fintech Compliance Ontology" ;
    rdfs:comment "An OWL ontology for monitoring account structures, ownership, and partner networks." .

# Classes
ex:Account a owl:Class .

ex:PersonalAccount a owl:Class ;
    rdfs:subClassOf ex:Account ;
    owl:disjointWith ex:CorporateAccount .

ex:CorporateAccount a owl:Class ;
    rdfs:subClassOf ex:Account .

ex:Party a owl:Class .

ex:Person a owl:Class ;
    rdfs:subClassOf ex:Party ;
    owl:disjointWith ex:Organization .

ex:Organization a owl:Class ;
    rdfs:subClassOf ex:Party .

# Equivalent Classes
ex:HighRiskAccount a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ex:Account
            [
                a owl:Restriction ;
                owl:onProperty ex:accountBalance ;
                owl:someValuesFrom [
                    a rdfs:Datatype ;
                    owl:onDatatype xsd:decimal ;
                    owl:withRestrictions ( [ xsd:minExclusive 100000.00 ] )
                ]
            ]
        )
    ] .

# Restrictions
ex:PersonalAccount rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:hasOwner ;
        owl:allValuesFrom ex:Person
    ] ,
    [
        a owl:Restriction ;
        owl:onProperty ex:hasSignatory ;
        owl:maxCardinality "3"^^xsd:nonNegativeInteger
    ] .

ex:CorporateAccount rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:hasOwner ;
        owl:allValuesFrom ex:Organization
    ] ,
    [
        a owl:Restriction ;
        owl:onProperty ex:hasOwner ;
        owl:cardinality "1"^^xsd:nonNegativeInteger
    ] .

# Properties
ex:hasOwner a owl:ObjectProperty .

ex:hasSignatory a owl:ObjectProperty ;
    rdfs:domain ex:PersonalAccount ;
    rdfs:range ex:Person .

ex:isPartnerOf a owl:ObjectProperty , owl:SymmetricProperty ;
    rdfs:domain ex:Organization ;
    rdfs:range ex:Organization .

ex:subAccountOf a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain ex:Account ;
    rdfs:range ex:Account .

ex:ownsAccount a owl:ObjectProperty ;
    owl:inverseOf ex:hasOwner .

ex:accountBalance a owl:DatatypeProperty ;
    rdfs:domain ex:Account ;
    rdfs:range xsd:decimal .

@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix ex:   <http://example.org/entertainment/> .

ex:EntertainmentOntology a owl:Ontology ;
    rdfs:label "Entertainment Media Ontology (IMDb)" ;
    rdfs:comment "An OWL ontology for modeling movies, TV series, actors, directors, and their roles." .

# Classes
ex:CreativeWork a owl:Class .

ex:Movie a owl:Class ;
    rdfs:subClassOf ex:CreativeWork ;
    owl:disjointWith ex:TVSeries .

ex:TVSeries a owl:Class ;
    rdfs:subClassOf ex:CreativeWork .

ex:RolePlayer a owl:Class .

ex:Actor a owl:Class ;
    rdfs:subClassOf ex:RolePlayer .

ex:Director a owl:Class ;
    rdfs:subClassOf ex:RolePlayer .

# Restrictions
ex:Actor rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:actedIn ;
        owl:someValuesFrom ex:CreativeWork
    ] .

ex:Director rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:directed ;
        owl:someValuesFrom ex:CreativeWork
    ] .

# Object Properties
ex:actedIn a owl:ObjectProperty ;
    rdfs:domain ex:Actor ;
    rdfs:range ex:CreativeWork .

ex:directed a owl:ObjectProperty ;
    rdfs:domain ex:Director ;
    rdfs:range ex:CreativeWork .

# Datatype Properties
ex:title a owl:DatatypeProperty ;
    rdfs:domain ex:CreativeWork ;
    rdfs:range xsd:string .

ex:releaseDate a owl:DatatypeProperty ;
    rdfs:domain ex:CreativeWork ;
    rdfs:range xsd:date .

ex:name a owl:DatatypeProperty ;
    rdfs:domain ex:RolePlayer ;
    rdfs:range xsd:string .

ex:characterName a owl:DatatypeProperty ;
    rdfs:domain ex:actedIn ;
    rdfs:range xsd:string .

ex:billingOrder a owl:DatatypeProperty ;
    rdfs:domain ex:actedIn ;
    rdfs:range xsd:integer .

@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix dcsa: <http://dcsa.org/ontology/> .

dcsa:DcsaOntology a owl:Ontology ;
    rdfs:label "DCSA-Aligned Container Shipping and Tracking Ontology" ;
    rdfs:comment "A simplified OWL ontology aligned with the Digital Container Shipping Association (DCSA) standards, modeling shipping bookings, equipment tracking, and transport calls." .

# ==========================================
# 1. CLASSES
# ==========================================

# Core Entities
dcsa:Booking a owl:Class .
dcsa:BillOfLading a owl:Class .
dcsa:Container a owl:Class .
dcsa:Vessel a owl:Class .

# Spatial/Location Context
dcsa:Location a owl:Class .
dcsa:Facility a owl:Class ;
    rdfs:subClassOf dcsa:Location .

# Logistics Port Activities
dcsa:TransportCall a owl:Class .

# Event Hierarchy (Tracking & Telemetry)
dcsa:Event a owl:Class .

dcsa:EquipmentEvent a owl:Class ;
    rdfs:subClassOf dcsa:Event ;
    owl:disjointWith dcsa:TransportEvent .

dcsa:TransportEvent a owl:Class ;
    rdfs:subClassOf dcsa:Event ;
    owl:disjointWith dcsa:ShipmentEvent .

dcsa:ShipmentEvent a owl:Class ;
    rdfs:subClassOf dcsa:Event .

# Equivalent Class: ActiveContainerEvent
dcsa:ActiveContainerEvent a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            dcsa:EquipmentEvent
            [
                a owl:Restriction ;
                owl:onProperty dcsa:eventClassifier ;
                owl:someValuesFrom [
                    a rdfs:Datatype ;
                    owl:onDatatype xsd:string ;
                    owl:withRestrictions ( [ xsd:pattern "ACTUAL" ] )
                ]
            ]
        )
    ] .

# ==========================================
# 2. OBJECT PROPERTIES
# ==========================================

dcsa:associatedWithBL a owl:ObjectProperty ;
    rdfs:domain dcsa:Booking ;
    rdfs:range dcsa:BillOfLading .

dcsa:bookingHasContainer a owl:ObjectProperty ;
    rdfs:domain dcsa:Booking ;
    rdfs:range dcsa:Container .

# Inverse Property: Container linked to Booking
dcsa:containerLinkedToBooking owl:inverseOf dcsa:bookingHasContainer .

dcsa:eventAtLocation a owl:ObjectProperty ;
    rdfs:domain dcsa:Event ;
    rdfs:range dcsa:Location .

dcsa:containerInEvent a owl:ObjectProperty ;
    rdfs:domain dcsa:EquipmentEvent ;
    rdfs:range dcsa:Container .

dcsa:callLocation a owl:ObjectProperty ;
    rdfs:domain dcsa:TransportCall ;
    rdfs:range dcsa:Location .

dcsa:callVessel a owl:ObjectProperty ;
    rdfs:domain dcsa:TransportCall ;
    rdfs:range dcsa:Vessel .

# Symmetric Property: Vessel Alliances / Sharing Agreements
dcsa:sharesAllianceWith a owl:ObjectProperty , owl:SymmetricProperty ;
    rdfs:domain dcsa:Vessel ;
    rdfs:range dcsa:Vessel .

# Transitive Property: Voyage route sequence (port leg connections)
dcsa:followedByLeg a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain dcsa:TransportCall ;
    rdfs:range dcsa:TransportCall .

# ==========================================
# 3. DATATYPE PROPERTIES
# ==========================================

dcsa:bookingReference a owl:DatatypeProperty ;
    rdfs:domain dcsa:Booking ;
    rdfs:range xsd:string .

dcsa:bolNumber a owl:DatatypeProperty ;
    rdfs:domain dcsa:BillOfLading ;
    rdfs:range xsd:string .

dcsa:containerNumber a owl:DatatypeProperty ;
    rdfs:domain dcsa:Container ;
    rdfs:range xsd:string .

dcsa:vesselImo a owl:DatatypeProperty ;
    rdfs:domain dcsa:Vessel ;
    rdfs:range xsd:integer .

dcsa:vesselName a owl:DatatypeProperty ;
    rdfs:domain dcsa:Vessel ;
    rdfs:range xsd:string .

dcsa:unLocode a owl:DatatypeProperty ;
    rdfs:domain dcsa:Location ;
    rdfs:range xsd:string .

dcsa:eventClassifier a owl:DatatypeProperty ;
    rdfs:domain dcsa:Event ;
    rdfs:range xsd:string . # E.g., "PLANNED", "ESTIMATED", "ACTUAL"

dcsa:eventDateTime a owl:DatatypeProperty ;
    rdfs:domain dcsa:Event ;
    rdfs:range xsd:dateTime .

# ==========================================
# 4. CLASS RESTRICTIONS
# ==========================================

dcsa:Container rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty dcsa:containerNumber ;
        owl:cardinality "1"^^xsd:nonNegativeInteger
    ] .

dcsa:TransportCall rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty dcsa:callVessel ;
        owl:someValuesFrom dcsa:Vessel
    ] .

@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix ex:   <http://example.org/ecommerce/> .

ex:EcommerceOntology a owl:Ontology ;
    rdfs:label "E-Commerce Customer Behavior and Product Recommendation Ontology" ;
    rdfs:comment "An OWL ontology for representing e-commerce transactions, product hierarchies, user reviews, and recommendation patterns." .

# ==========================================
# 1. CLASSES
# ==========================================

# User Taxonomy
ex:User a owl:Class .

ex:Customer a owl:Class ;
    rdfs:subClassOf ex:User ;
    owl:disjointWith ex:Merchant .

ex:Merchant a owl:Class ;
    rdfs:subClassOf ex:User .

# Product Taxonomy
ex:Product a owl:Class .

ex:Book a owl:Class ;
    rdfs:subClassOf ex:Product ;
    owl:disjointWith ex:Electronics .

ex:Electronics a owl:Class ;
    rdfs:subClassOf ex:Product ;
    owl:disjointWith ex:Clothing .

ex:Clothing a owl:Class ;
    rdfs:subClassOf ex:Product .

# Transactional/Interactivity Classes
ex:Order a owl:Class .
ex:Review a owl:Class .
ex:Category a owl:Class .

# Equivalent Class: HighRatingReview
ex:HighRatingReview a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ex:Review
            [
                a owl:Restriction ;
                owl:onProperty ex:ratingValue ;
                owl:someValuesFrom [
                    a rdfs:Datatype ;
                    owl:onDatatype xsd:integer ;
                    owl:withRestrictions ( [ xsd:minInclusive 4 ] )
                ]
            ]
        )
    ] .

# ==========================================
# 2. OBJECT PROPERTIES
# ==========================================

ex:placedOrder a owl:ObjectProperty ;
    rdfs:domain ex:Customer ;
    rdfs:range ex:Order .

ex:orderContains a owl:ObjectProperty ;
    rdfs:domain ex:Order ;
    rdfs:range ex:Product .

ex:reviewedBy a owl:ObjectProperty ;
    rdfs:domain ex:Review ;
    rdfs:range ex:Customer .

ex:reviewFor a owl:ObjectProperty ;
    rdfs:domain ex:Review ;
    rdfs:range ex:Product .

ex:hasCategory a owl:ObjectProperty ;
    rdfs:domain ex:Product ;
    rdfs:range ex:Category .

# Transitive Property: Category Hierarchy
ex:subCategoryOf a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain ex:Category ;
    rdfs:range ex:Category .

ex:parentCategoryOf a owl:ObjectProperty ;
    owl:inverseOf ex:subCategoryOf .

# Symmetric Property: Recommendations (Products frequently bought together)
ex:frequentlyBoughtWith a owl:ObjectProperty , owl:SymmetricProperty ;
    rdfs:domain ex:Product ;
    rdfs:range ex:Product .

# ==========================================
# 3. DATATYPE PROPERTIES
# ==========================================

ex:userId a owl:DatatypeProperty ;
    rdfs:domain ex:User ;
    rdfs:range xsd:string .

ex:userName a owl:DatatypeProperty ;
    rdfs:domain ex:User ;
    rdfs:range xsd:string .

ex:productPrice a owl:DatatypeProperty ;
    rdfs:domain ex:Product ;
    rdfs:range xsd:decimal .

ex:orderId a owl:DatatypeProperty ;
    rdfs:domain ex:Order ;
    rdfs:range xsd:string .

ex:orderDate a owl:DatatypeProperty ;
    rdfs:domain ex:Order ;
    rdfs:range xsd:dateTime .

ex:ratingValue a owl:DatatypeProperty ;
    rdfs:domain ex:Review ;
    rdfs:range xsd:integer .

ex:reviewText a owl:DatatypeProperty ;
    rdfs:domain ex:Review ;
    rdfs:range xsd:string .

ex:categoryName a owl:DatatypeProperty ;
    rdfs:domain ex:Category ;
    rdfs:range xsd:string .

# ==========================================
# 4. CLASS RESTRICTIONS
# ==========================================

ex:Customer rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:placedOrder ;
        owl:someValuesFrom ex:Order
    ] .

ex:Order rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:orderContains ;
        owl:someValuesFrom ex:Product
    ] .

@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix fibo: <http://spec.edmcouncil.org/fibo/ontology/> .

fibo:FiboOntology a owl:Ontology ;
    rdfs:label "FIBO-Aligned Financial Instrument and Business Entity Ontology" ;
    rdfs:comment "A simplified OWL ontology aligned with the Financial Industry Business Ontology (FIBO), covering legal entities, shares, loans, and corporate control chains." .

# ==========================================
# 1. CLASSES
# ==========================================

fibo:AutonomousAgent a owl:Class .

# Business Entity Taxonomy
fibo:LegalEntity a owl:Class ;
    rdfs:subClassOf fibo:AutonomousAgent .

fibo:Corporation a owl:Class ;
    rdfs:subClassOf fibo:LegalEntity ;
    owl:disjointWith fibo:Partnership .

fibo:Partnership a owl:Class ;
    rdfs:subClassOf fibo:LegalEntity .

# Contractual Roles
fibo:ContractualParty a owl:Class ;
    rdfs:subClassOf fibo:AutonomousAgent .

# Financial Instrument Taxonomy
fibo:FinancialInstrument a owl:Class .

fibo:Security a owl:Class ;
    rdfs:subClassOf fibo:FinancialInstrument .

fibo:Share a owl:Class ;
    rdfs:subClassOf fibo:Security ;
    owl:disjointWith fibo:DebtInstrument .

fibo:DebtInstrument a owl:Class ;
    rdfs:subClassOf fibo:Security .

fibo:Loan a owl:Class ;
    rdfs:subClassOf fibo:FinancialInstrument .

# Equivalent Class: SignificantCorporateLoan
fibo:SignificantCorporateLoan a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fibo:Loan
            [
                a owl:Restriction ;
                owl:onProperty fibo:loanAmount ;
                owl:someValuesFrom [
                    a rdfs:Datatype ;
                    owl:onDatatype xsd:decimal ;
                    owl:withRestrictions ( [ xsd:minExclusive 10000000.00 ] )
                ]
            ]
        )
    ] .

# ==========================================
# 2. OBJECT PROPERTIES
# ==========================================

fibo:hasLender a owl:ObjectProperty ;
    rdfs:domain fibo:Loan ;
    rdfs:range fibo:ContractualParty .

fibo:hasBorrower a owl:ObjectProperty ;
    rdfs:domain fibo:Loan ;
    rdfs:range fibo:ContractualParty .

fibo:issuedBy a owl:ObjectProperty ;
    rdfs:domain fibo:Security ;
    rdfs:range fibo:LegalEntity .

# Inverse Property: LegalEntity issues Security
fibo:isIssuerOf owl:inverseOf fibo:issuedBy .

fibo:ownedBy a owl:ObjectProperty ;
    rdfs:domain fibo:Share ;
    rdfs:range fibo:LegalEntity .

fibo:guaranteedBy a owl:ObjectProperty ;
    rdfs:domain fibo:Loan ;
    rdfs:range fibo:LegalEntity .

# Symmetric Property: Co-guarantor alliances
fibo:sharesGuarantorRiskWith a owl:ObjectProperty , owl:SymmetricProperty ;
    rdfs:domain fibo:LegalEntity ;
    rdfs:range fibo:LegalEntity .

# Transitive Property: Corporate parent/subsidiary control chains
fibo:controlledBy a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain fibo:LegalEntity ;
    rdfs:range fibo:LegalEntity .

fibo:controlsLegalEntity owl:inverseOf fibo:controlledBy .

# ==========================================
# 3. DATATYPE PROPERTIES
# ==========================================

fibo:leiCode a owl:DatatypeProperty ;
    rdfs:domain fibo:LegalEntity ;
    rdfs:range xsd:string .

fibo:legalName a owl:DatatypeProperty ;
    rdfs:domain fibo:LegalEntity ;
    rdfs:range xsd:string .

fibo:isinCode a owl:DatatypeProperty ;
    rdfs:domain fibo:Security ;
    rdfs:range xsd:string .

fibo:loanAmount a owl:DatatypeProperty ;
    rdfs:domain fibo:Loan ;
    rdfs:range xsd:decimal .

fibo:interestRate a owl:DatatypeProperty ;
    rdfs:domain fibo:Loan ;
    rdfs:range xsd:decimal .

fibo:sharesOutstanding a owl:DatatypeProperty ;
    rdfs:domain fibo:Share ;
    rdfs:range xsd:integer .

# ==========================================
# 4. CLASS RESTRICTIONS
# ==========================================

fibo:LegalEntity rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty fibo:leiCode ;
        owl:cardinality "1"^^xsd:nonNegativeInteger
    ] .

fibo:Loan rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty fibo:hasLender ;
        owl:someValuesFrom fibo:ContractualParty
    ] .

@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix ex:   <http://example.org/fintech/> .

ex:FintechOntology a owl:Ontology ;
    rdfs:label "Fintech Compliance Ontology" ;
    rdfs:comment "An OWL ontology for monitoring account structures, ownership, and partner networks." .

# Classes
ex:Account a owl:Class .

ex:PersonalAccount a owl:Class ;
    rdfs:subClassOf ex:Account ;
    owl:disjointWith ex:CorporateAccount .

ex:CorporateAccount a owl:Class ;
    rdfs:subClassOf ex:Account .

ex:Party a owl:Class .

ex:Person a owl:Class ;
    rdfs:subClassOf ex:Party ;
    owl:disjointWith ex:Organization .

ex:Organization a owl:Class ;
    rdfs:subClassOf ex:Party .

# Equivalent Classes
ex:HighRiskAccount a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ex:Account
            [
                a owl:Restriction ;
                owl:onProperty ex:accountBalance ;
                owl:someValuesFrom [
                    a rdfs:Datatype ;
                    owl:onDatatype xsd:decimal ;
                    owl:withRestrictions ( [ xsd:minExclusive 100000.00 ] )
                ]
            ]
        )
    ] .

# Restrictions
ex:PersonalAccount rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:hasOwner ;
        owl:allValuesFrom ex:Person
    ] ,
    [
        a owl:Restriction ;
        owl:onProperty ex:hasSignatory ;
        owl:maxCardinality "3"^^xsd:nonNegativeInteger
    ] .

ex:CorporateAccount rdfs:subClassOf
    [
        a owl:Restriction ;
        owl:onProperty ex:hasOwner ;
        owl:allValuesFrom ex:Organization
    ] ,
    [
        a owl:Restriction ;
        owl:onProperty ex:hasOwner ;
        owl:cardinality "1"^^xsd:nonNegativeInteger
    ] .

# Properties
ex:hasOwner a owl:ObjectProperty .

ex:hasSignatory a owl:ObjectProperty ;
    rdfs:domain ex:PersonalAccount ;
    rdfs:range ex:Person .

ex:isPartnerOf a owl:ObjectProperty , owl:SymmetricProperty ;
    rdfs:domain ex:Organization ;
    rdfs:range ex:Organization .

ex:subAccountOf a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain ex:Account ;
    rdfs:range ex:Account .

ex:ownsAccount a owl:ObjectProperty ;
    owl:inverseOf ex:hasOwner .

ex:accountBalance a owl:DatatypeProperty ;
    rdfs:domain ex:Account ;
    rdfs:range xsd:decimal .

@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix ex:   <http://example.org/cybersecurity/> .

ex:CybersecurityOntology a owl:Ontology ;
    rdfs:label "Cybersecurity Network Threat Intelligence and Vulnerability Ontology" ;
    rdfs:comment "An OWL ontology modeling network topologies, host configurations, user sessions, vulnerabilities, and threat actors." .

# ==========================================
# 1. CLASSES
# ==========================================

# Network Nodes
ex:NetworkNode a owl:Class .

ex:Endpoint a owl:Class ;
    rdfs:subClassOf ex:NetworkNode ;
    owl:disjointWith ex:Gateway .

ex:Gateway a owl:Class ;
    rdfs:subClassOf ex:NetworkNode .

ex:Server a owl:Class ;
    rdfs:subClassOf ex:Endpoint ;
    owl:disjointWith ex:Workstation .

ex:Workstation a owl:Class ;
    rdfs:subClassOf ex:Endpoint .

# Logical/Security Concepts
ex:IPAddress a owl:Class .
ex:Vulnerability a owl:Class .
ex:ThreatActor a owl:Class .
ex:SecurityAlert a owl:Class .
ex:SystemProcess a owl:Class .
ex:UserAccount a owl:Class .

# Equivalent Class: CriticalSeverityAlert
ex:CriticalSeverityAlert a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ex:SecurityAlert
            [
                a owl:Restriction ;
                owl:onProperty ex:severityScore ;
                owl:someValuesFrom [
                    a rdfs:Datatype ;
                    owl:onDatatype xsd:integer ;
                    owl:withRestrictions ( [ xsd:minInclusive 9 ] )
                ]
            ]
        )
    ] .

# ==========================================
# 2. OBJECT PROPERTIES
# ==========================================

ex:hasIPAddress a owl:ObjectProperty ;
    rdfs:domain ex:Endpoint ;
    rdfs:range ex:IPAddress .

# Inverse Property: IP belongs to endpoint
ex:ipBelongsTo owl:inverseOf ex:hasIPAddress .

ex:hasVulnerability a owl:ObjectProperty ;
    rdfs:domain ex:Endpoint ;
    rdfs:range ex:Vulnerability .

ex:exploits a owl:ObjectProperty ;
    rdfs:domain ex:ThreatActor ;
    rdfs:range ex:Vulnerability .

ex:compromisedBy a owl:ObjectProperty ;
    rdfs:domain ex:Endpoint ;
    rdfs:range ex:ThreatActor .

ex:loggedInFrom a owl:ObjectProperty ;
    rdfs:domain ex:UserAccount ;
    rdfs:range ex:Endpoint .

ex:triggeredAlert a owl:ObjectProperty ;
    rdfs:domain ex:Endpoint ;
    rdfs:range ex:SecurityAlert .

# Symmetric Property: Network Connection
ex:communicatedWith a owl:ObjectProperty , owl:SymmetricProperty ;
    rdfs:domain ex:Endpoint ;
    rdfs:range ex:Endpoint .

# Transitive Property: Process Trees
ex:parentProcessOf a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain ex:SystemProcess ;
    rdfs:range ex:SystemProcess .

ex:childProcessOf a owl:ObjectProperty ;
    owl:inverseOf ex:parentProcessOf .

# ==========================================
